```js
class TrieNode {
  constructor() {
    this.children = {}; // Map from char to TrieNode
    this.isEndOfWord = false; // Marks end of word
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }
}
```

```js
insert(word) {
  let node = this.root;
  for (const char of word) {
    if (!node.children[char]) {
      node.children[char] = new TrieNode();
    }
    node = node.children[char];
  }
  node.isEndOfWord = true;
}
```

```js
search(word) {
  let node = this.root;
  for (const char of word) {
    if (!node.children[char]) return false;
    node = node.children[char];
  }
  return node.isEndOfWord;
}
```

```js
startsWith(prefix) {
  let node = this.root;
  for (const char of prefix) {
    if (!node.children[char]) return false;
    node = node.children[char];
  }
  return true;
}

// Autocomplete collects all words with given prefix
collectAllWords(node = this.root, prefix = '', words = []) {
  if (node.isEndOfWord) words.push(prefix);
  for (const char in node.children) {
    this.collectAllWords(node.children[char], prefix + char, words);
  }
  return words;
}
```

```js
delete(word, node = this.root, depth = 0) {
  if (!node) return false;
  if (depth === word.length) {
    if (!node.isEndOfWord) return false;
    node.isEndOfWord = false;
    return Object.keys(node.children).length === 0;
  }
  const char = word[depth];
  if (!node.children[char]) return false;
  const shouldDeleteChild = this.delete(word, node.children[char], depth + 1);
  if (shouldDeleteChild) {
    delete node.children[char];
    return Object.keys(node.children).length === 0 && !node.isEndOfWord;
  }
  return false;
}
```
